     "targetTriple": "operational platform",
     "hostTriple": "operational platform",
     "sysrootDigest": "retained artifact of the resolution environment, not a language identity",
     "rustcDevLlvmDigest": "code generation backend; it does not interpret a body span",
     "standardLibraryComponentDigests": "resolution inputs, not body interpretation",
     "cargoVersion": "build and dependency tool; it does not read the body",
     "resolverVersion": "dependency resolution, not language",
     "crateRootPaths": "paths, and a body identity must not vary with where a crate sits",
     "editionMapKeys": "crate NAMES; one body identity must not depend on unrelated crates"
    },
    "dialectRepresentableForm": "An ordinary mixed-edition workspace has a representable valid form: each source path is owned by units of one edition, so every body gets its own dialect and bodies of BOTH editions close in the same universe. Only a path genuinely compiled under two different editions refuses.",
