 "coverageTotality": {
  "rung": "enumerated",
  "over": "subjects",
  "matchOn": [
   "snapshotId",
   "relation",
   "resolution",
   "sourceUniverse",
   "targetUniverse"
  ],
  "matchLaw": "A fact discharges THIS scope's obligation only if it agrees with the scope on EVERY coordinate listed in matchOn. Those are the four CoverageKeyV2 coordinates other than the subject-scope commitment itself, plus the owning snapshot. An earlier revision matched relation and resolution ALONE, and that is not enough in a view that carries more than one universe: the view-level fact/scope join is EXISTENTIAL - each fact must agree with SOME scope on relation, rung and both universes - so a TypeScript file fact is lawfully in a view that also carries a syntax-universe scope, and it then paid that scope's missing-file obligation. A complete Run exhibited exactly that (root diagnostic attempt3: two complete file@enumerated scopes for `a.ts`, only the TypeScript fact, ADMIT). Totality is a claim about what THIS universe examined, so it must be discharged by evidence produced in THIS universe; a fact from another universe is a different interpretation of the same bytes and is not the same observation.",
  "snapshotIsListedDeliberately": "The owning snapshot is already forced transitively - Run closure requires every fact and every subject-scope to carry the Run's own snapshotId - so listing it changes no outcome today, and a control confirms the transitive refusal (REFERENCE_SOURCE_JOIN). It is listed anyway because this law reads ONE scope's obligation out of a SHARED view, and a join that silently depends on an invariant enforced somewhere else is the same class of implicit coupling that produced the cross-universe defect.",
  "pathField": "path",
  "rule": "When a subject-scope for file@enumerated carries entry.coverage `complete`, every one of its subjects that appears in the analysed snapshot sourceInventory must have an admitted file@enumerated fact in the same view whose payload `path` is that subject. A subject outside the inventory is owed nothing.",
  "refusal": "COVERAGE_INVENTORY_TOTALITY_OMITS_PATH"
 },
 "rungs": {},
 "snapshotJoins": [
  {
   "form": "inventoried-file",
   "pathField": "path",
   "digestField": "contentSha256",
   "lengthField": "byteLength",
   "retainedBlob": true,
   "anchorPathField": "path",
   "note": "anchorPathField closes the second-owner case: a file payload is admissible only under a fact whose every anchor lies in the very file the payload claims, so an arbitrary anchor can never be borrowed to satisfy a foreign file claim. It is universally quantified, so it says nothing at zero anchors and it never covered `package` or `vcs-change` at all; the registry `anchorLaw` now closes the inventory class at zero anchors and refuses the borrowed anchor for all three relations before this row is reached. This row is retained as the narrower statement it always was, not as the operative inventory defence."
  }
 ]
}
{
 "field": "bodyIdentity",
 "levelField": "normalisationLevel",
 "levelVersionField": "normalisationVersion",
 "domainTag": "opensip.fact-identity.v1",
 "inheritedFrom": "docs/coop/artifacts/fact-identity-policy.v2.json#/canonicalisationSchema",
 "levelSpecificationRetained": "normalisationVersion names the retained level specification bytes",
 "recomputableAt": [
  "L0-verbatim"
 ],
 "note": "At L0 the canonical payload is the raw body-span bytes, so the host recomputes it from the enclosing fact anchor: a real source join. At L1-L3 it is a versioned normalizer output the host cannot recompute, so the requirement is exact retained preimage custody plus the framed-identity check. This is custody and framing evidence; it qualifies no normalizer.",
 "anchorCardinality": 1,
 "anchorRule": "A clones fact carries exactly one anchor: the body span the identity is over. Zero anchors would leave the claim unattached and several would make the L0 recomputation a choice, which is the arbitrary-anchor defect in another form. `anchorCardinality` here is a declared MIRROR of this relation's registry `anchorLaw` (class `body-identity`, cardinality 1), which is the single enforcing statement and is applied to every relation before any payload join runs. The join checks that the two AGREE (`RELATION_ANCHOR_LAW_DRIFT`) rather than refusing the same fault a second time under a second name.",
 "languageIdSource": "the BODY's language, from the SAME selector over the SAME single anchor that produces the body dialect: the `languageVersionBinding` of the fact sourceUniverse domain registry row, where `dialect.form` is `closed-suffix-table` gives `bodyLanguageByVariant[<the variant that table selects from this anchor's path suffix, longest match wins>]`, and any other dialect form gives `bodyLanguage`. The value is always a member of that row's `bodyLanguages` and of the closed foundation `#/$defs/body-language-version` `languageId` enum {javascript, rust, typescript}.",
 "languageIdIsNotTheProviderLanguage": "It is emphatically NOT the domain row's own `language` field. That field names the ENGINE that read the body, and the two differ in both live cases: a `.js` body under `native.semantic-universe.typescript.v2` is a `javascript` body, not `typescript`, and every body under `native.semantic-universe.syntax.v2` would read as `syntax`, which the closed languageId enum does not contain, so a literal implementer would mint a different clone identity for every JavaScript body and NO admissible identity at all under the syntax universe. An earlier revision of this key said `the language of the fact sourceUniverse domain registry row`, which is that wrong reading; identity-and-evidence section 3 and each domain row's own `bodyLanguageLaw` always said the derived one, and the identity-model body-identity join has always checked the derived projection. This key is now the same sentence as those two.",
 "languageVersionSource": "the raw 32 bytes of SHA-256(C(body-language-version)), the closed DERIVED record at foundation/identity-schemas.v2.json#/$defs/body-language-version, rebuilt by Run closure from the universe ResolvedInputs and the admitted retained native context the universe own nativeContextId names, per that universe domain languageVersionBinding. It carries the identity of the component that INTERPRETS the body span plus the selected source dialect; it never carries a human display string, an option-synthesis version, an operational platform value, a path, or a whole per-crate map. Fixed width, because the inherited frame gives each component a u8 length.",
 "tokenStreamFraming": "u32be token_count || token*, token = u16be kind_id_len || kind_id || u32be value_len || value. The closure parses the retained L1-L3 stream to prove custody and framing; it does not and must not judge the tokenisation itself."
}
