def find(node, want, path=""):
    out=[]
    if isinstance(node,dict):
        for k,v in node.items():
            if k in want: out.append((path+"/"+k, v))
            out += find(v, want, path+"/"+k)
    elif isinstance(node,list):
        for i,v in enumerate(node): out += find(v, want, f"{path}/{i}")
    return out
for p,v in find(d, {"faultCause","faultCauses","declaredCauses","causes"}):
    s=json.dumps(v)
    if len(s)<900: print(p, s)
