      "host-invariant" in json.dumps(d))
print("'SYSTEM.OUTCOME.ILLEGAL_STATE' occurs:", "SYSTEM.OUTCOME.ILLEGAL_STATE" in json.dumps(d))
for p,v in find(d, {"classes","exitCodes","precedence","aggregation","nonAnalysisDerivation","codeMaps","axes"}):
    s=json.dumps(v)
    print("\n==",p, s[:1200])
EOF

